match (self.default_fallback, default_fallback) {
    // both have the default fallback
    // keep the nested fallbacks from both
    (true, true) => {
        panic_on_err!(
            self.fallback_router
                .merge(other_fallback.without_root_fallback())
        );
    }
    // self has default fallback, other has a custom fallback
    // use the root fallback from other and keep self's nested fallbacks
    (true, false) => {
